from pathlib import Path
p = Path('streamlit_app (7).py')
s = p.read_text(encoding='utf-8')

# Fix duplicated uploader text without creating another uploader.
old_css = '''[data-testid="stFileUploaderDropzone"]{background:#f8fafc!important;border:1.5px dashed #cbd5e1!important;border-radius:14px!important}[data-testid="stFileUploaderDropzone"] button{background:#fff!important;border:1px solid #bfdbfe!important;border-radius:8px!important}'''
new_css = '''[data-testid="stFileUploaderDropzone"]{background:#f8fafc!important;border:1.5px dashed #cbd5e1!important;border-radius:14px!important}[data-testid="stFileUploaderDropzone"] button{background:#fff!important;border:1px solid #bfdbfe!important;border-radius:8px!important;font-size:0!important;line-height:1!important;white-space:nowrap!important;overflow:hidden!important}[data-testid="stFileUploaderDropzone"] button span{font-size:0!important}[data-testid="stFileUploaderDropzone"] button::after{content:"اختيار ملف";font-family:'Cairo',sans-serif!important;font-size:13px!important;font-weight:700!important;line-height:1.2!important;color:#2563eb!important}'''
if old_css in s:
    s = s.replace(old_css, new_css, 1)

# Keep the student search deduplicated, preferring the latest real status.
start = s.find('def get_students(office_id, search=""):\n')
end = s.find('\ndef status_class(status):', start)
if start == -1 or end == -1:
    raise SystemExit('get_students block not found')
new_func = '''def get_students(office_id, search=""):\n    rows=(\n        db().table("student_records")\n        .select("id,student_name,login_identifier,application_status,status_updated_at,source_row_number,created_at,updated_at")\n        .eq("office_id",office_id)\n        .execute().data or []\n    )\n\n    def _ts(value):\n        text=str(value or "").strip()\n        if not text:\n            return datetime.min.replace(tzinfo=timezone.utc)\n        try:\n            return datetime.fromisoformat(text.replace("Z","+00:00"))\n        except Exception:\n            return datetime.min.replace(tzinfo=timezone.utc)\n\n    latest={}\n    for row in rows:\n        key=str(row.get("login_identifier") or row.get("student_name") or "").strip().lower()\n        if not key:\n            continue\n        score=(_ts(row.get("status_updated_at")),_ts(row.get("updated_at")),_ts(row.get("created_at")))\n        current=latest.get(key)\n        if current is None or score > current[0]:\n            latest[key]=(score,row)\n    rows=[item[1] for item in latest.values()]\n    rows=sorted(rows,key=lambda r:str(r.get("student_name") or "").lower())\n    if search.strip():\n        q=search.strip().lower()\n        rows=[r for r in rows if q in str(r.get("student_name","")).lower()]\n    return rows\n'''
s = s[:start] + new_func + s[end:]

# Replace the fallback worker so one bad student never stops the batch,
# and technical failures are retried once after the first full pass.
start = s.find('def _run_legacy_api_fallback(job):\n')
end = s.find('\ndef wait_for_worker_or_legacy_fallback(job_id):', start)
if start == -1 or end == -1:
    raise SystemExit('legacy fallback block not found')
new_fallback = '''def _run_legacy_api_fallback(job):\n    students = (\n        db().table("student_records")\n        .select("*")\n        .eq("office_id", job["office_id"])\n        .eq("data_source_id", job["data_source_id"])\n        .order("source_row_number")\n        .execute().data or []\n    )\n    students = [\n        row for row in students\n        if str(row.get("application_status") or "").strip() not in FINAL_STATUSES\n        and row.get("login_identifier")\n        and row.get("encrypted_password")\n    ]\n    if not students:\n        db().table("jobs").update({"status": "done", "finished_at": now_iso()}).eq("id", job["id"]).execute()\n        return\n\n    total = len(students)\n    live_table = st.empty()\n    live_rows = []\n    technical_failures = []\n\n    def check_one(student):\n        session = None\n        status = "خطأ فني في الفحص"\n        technical = False\n        error_text = ""\n        try:\n            session, token, error = _legacy_api_login(\n                student["login_identifier"],\n                _decrypt_student_password(student["encrypted_password"]),\n            )\n            if error:\n                status = "فشل تسجيل الدخول"\n            else:\n                status = _legacy_api_get_status(session, token)\n                technical = str(status).startswith("خطأ")\n                if technical:\n                    status = "خطأ فني في الفحص"\n        except Exception as exc:\n            technical = True\n            error_text = str(exc)\n            status = "خطأ فني في الفحص"\n        finally:\n            _legacy_api_logout(session)\n        return status, technical, error_text\n\n    def save_result(student, status, index_for_progress):\n        stamp = now_iso()\n        student_id = student["id"]\n        # DB failure for one student must not stop the remaining students.\n        try:\n            db().table("student_records").update({\n                "application_status": status,\n                "status_updated_at": stamp,\n                "updated_at": stamp,\n            }).eq("id", student_id).execute()\n        except Exception as exc:\n            print(f"Student status save error for {student_id}: {exc}")\n        student_display = student.get("student_name") or student.get("login_identifier")\n        try:\n            db().table("job_progress").insert({\n                "job_id": job["id"],\n                "student_index": index_for_progress,\n                "total": total,\n                "student_name": student_display,\n                "status": status,\n            }).execute()\n        except Exception as exc:\n            print(f"Progress save error for {student_id}: {exc}")\n        live_rows.append({"اسم الطالب": student_display, "الحالة الجديدة": status})\n        live_table.dataframe(pd.DataFrame(live_rows), use_container_width=True, hide_index=True)\n\n    # الجولة الأولى: كل الطلاب، من غير ما طالب واحد يوقف الباقي.\n    for index, student in enumerate(students, 1):\n        status, technical, error_text = check_one(student)\n        if technical:\n            technical_failures.append({"student": student, "error": error_text or status})\n        save_result(student, status, index)\n\n    # الجولة الثانية: بعد انتهاء كل الطلاب، أعد فحص كل خطأ فني مرة واحدة.\n    if technical_failures:\n        live_table.markdown("**🔁 إعادة فحص الطلاب الذين ظهر لهم خطأ فني...**")\n        for retry_index, item in enumerate(technical_failures, 1):\n            student = item["student"]\n            status, technical, error_text = check_one(student)\n            save_result(student, status, total + retry_index)\n\n    remaining_tech = []\n    for item in technical_failures:\n        student_id = item["student"]["id"]\n        try:\n            row = (\n                db().table("student_records")\n                .select("application_status")\n                .eq("id", student_id)\n                .limit(1)\n                .execute().data or []\n            )\n            if row and str(row[0].get("application_status") or "").strip() == "خطأ فني في الفحص":\n                remaining_tech.append(item)\n        except Exception:\n            # Keep the failure list for logging if the verification query itself fails.\n            remaining_tech.append(item)\n\n    db().table("jobs").update({\n        "status": "failed" if len(remaining_tech) >= total else "done",\n        "finished_at": now_iso(),\n        "error": "فشل فني في كل الطلاب" if len(remaining_tech) >= total else None,\n    }).eq("id", job["id"]).execute()\n'''
s = s[:start] + new_fallback + s[end:]
p.write_text(s, encoding='utf-8')
print('fallback retry and search patch applied')